1	import React, { type CSSProperties } from 'react';
2	import { Button as ChakraButton, IconButton, type SystemStyleObject } from '@chakra-ui/react';
3	import { ZimmIcon } from '../zimmIcon';
4	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
5	
6	// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
7	// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
8	// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
9	
10	type ZimmButtonBaseProps = {
11	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
12	  label: string;
13	  type?: 'button' | 'submit' | 'reset';
14	  disabled?: boolean;
15	  inverse?: boolean;
16	  onClick?: () => void;
17	  style?: CSSProperties;
18	  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
19	  sx?: SystemStyleObject;
20	};
21	
22	type ZimmLabelButtonProps = ZimmButtonBaseProps & {
23	  variant?: 'primary' | 'secondary';
24	  size?: 'large' | 'medium';
25	  fullWidth?: boolean;
26	};
27	
28	type ZimmIconButtonProps = ZimmButtonBaseProps & {
29	  variant: 'icon';
30	  icon: ZimmIconType;
31	  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
32	  size?: ZimmIconSize;
33	};
34	
35	type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;
36	
37	const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';
38	
39	/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
40	 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus. */
41	export const ZimmButton = (props: ZimmButtonProps) => {
42	  const { label, type = 'button', disabled = false, inverse = false, onClick, style, sx } = props;
43	
44	  if (props.variant === 'icon') {
45	    return (
46	      <IconButton
47	        aria-label={label}
48	        type={type}
49	        isDisabled={disabled}
50	        onClick={onClick}
51	        variant={inverse ? 'iconInverse' : 'icon'}
52	        size="icon"
53	        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
54	        style={style}
55	        sx={sx}
56	      />
57	    );
58	  }
59	
60	  const variant = props.variant ?? 'primary';
61	  const size = props.size === 'medium' ? 'sm' : 'lg';
62	  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
63	  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;
64	
65	  return (
66	    <ChakraButton
67	      type={type}
68	      isDisabled={disabled}
69	      onClick={onClick}
70	      variant={chakraVariant}
71	      size={size}
72	      width={props.fullWidth ? '100%' : undefined}
73	      style={style}
74	      sx={sx}
75	    >
76	      {label}
77	    </ChakraButton>
78	  );
79	};
